def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with the given values
    grid = [[0] * N for _ in range(N)]
    for value in grid_values:
        grid[value[0]][value[1]] = value[2]

    # Initialize the maximum sums and predecessors
    max_sums = [[0] * N for _ in range(N)]
    predecessors = [[None] * N for _ in range(N)]

    # Dynamic programming to find the maximum sum and predecessors
    for i in range(N):
        for j in range(N):
            max_sums[i][j] = grid[i][j] + max(max_sums[i - 1][j], max_sums[i][j - 1])
            if max_sums[i - 1][j] > max_sums[i][j - 1]:
                predecessors[i][j] = (i - 1, j)
            else:
                predecessors[i][j] = (i, j - 1)

    # Recover the two paths
    path1 = []
    path2 = []
    i, j = N - 1, N - 1
    while i != 0 or j != 0:
        if predecessors[i][j] == (i - 1, j):
            path1.append((i, j))
            i -= 1
        else:
            path2.append((i, j))
            j -= 1

    # Return the maximum sum of values collected on the two paths
    return sum(grid[i][j] for i, j in path1) + sum(grid[i][j] for i, j in path2)
