    """
    Optimize the placement of aisles in a classroom to minimize the amount of chatting between students.
    Args:
        M (int): The number of rows in the classroom.
        N (int): The number of columns in the classroom.
        K (int): The number of horizontal aisles to add.
        L (int): The number of vertical aisles to add.
        D (int): The number of chatting pairs in the classroom.
        chatting_pairs (list of tuples): A list of tuples, each containing the positions (Xi, Yi) and (Pi, Qi) of a chatting pair.
    Returns:
        (str, str): Two space-separated strings representing the optimal row and column indices for the aisles.
    """
    # Initialize variables
    num_rows = M
    num_cols = N
    num_horiz_aisles = K
    num_vert_aisles = L
    num_chatting_pairs = D
    chatting_pairs_list = chatting_pairs

    # Create a dictionary to store the count of chatting pairs that can be separated by each possible aisle
    aisle_count = {}
    for i in range(num_rows):
        aisle_count[i] = {}
        for j in range(num_cols):
            aisle_count[i][j] = 0

    # Iterate through each chatting pair and increment the count for each possible aisle that can separate them
    for (Xi, Yi), (Pi, Qi) in chatting_pairs_list:
        for i in range(num_rows):
            for j in range(num_cols):
                if (Xi < i < Pi or Xi > i > Pi) and (Yi < j < Qi or Yi > j > Qi):
                    aisle_count[i][j] += 1

    # Select the most effective positions for the aisles
    horiz_aisles = []
    vert_aisles = []
    for i in range(num_horiz_aisles):
        max_count = 0
        max_row = 0
        for row in aisle_count:
            for col in aisle_count[row]:
                if aisle_count[row][col] > max_count:
                    max_count = aisle_count[row][col]
                    max_row = row
        horiz_aisles.append(max_row)
        for col in aisle_count[max_row]:
            aisle_count[max_row][col] = 0

    for i in range(num_vert_aisles):
        max_count = 0
        max_col = 0
        for col in aisle_count[max_row]:
            for row in aisle_count:
                if aisle_count[row][col] > max_count:
                    max_count = aisle_count[row][col]
                    max_col = col
        vert_aisles.append(max_col)
        for row in aisle_count:
            aisle_count[row][max_col] = 0

    # Return the optimal row and column indices for the aisles
    return ' '.join(map(str, horiz_aisles)), ' '.join(map(str, vert_aisles))
