    Returns:
        int: The total count of unique numbers that can be generated.
    """
    queue = [n]
    visited = set()
    while queue:
        num = queue.pop(0)
        if num not in visited:
            visited.add(num)
            for rule in rules:
                new_num = None
                if len(str(num)) == 1:
                    new_num = rule[0]
                else:
                    for i in range(len(str(num))):
                        if str(num)[i] == str(rule[0]):
