def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize the dp table with 0 for all indices
    dp = [[0 for _ in range(T+1)] for _ in range(M+1)]

    # Fill in the values for the first row
    for i in range(1, M+1):
        dp[i][0] = 0

    # Fill in the values for the first column
    for j in range(1, T+1):
        dp[0][j] = 0

    # Fill in the values for the remaining cells
    for i in range(1, M+1):
        for j in range(1, T+1):
            # Case 1: Pick the current herb
            time_cost, value = herbs[i-1]
            if j >= time_cost:
                dp[i][j] = max(dp[i-1][j-time_cost] + value, dp[i-1][j])
            # Case 2: Do not pick the current herb
            else:
                dp[i][j] = dp[i-1][j]

    return dp[M][T]
